// src/components/launch/sections/ResourcesSection.jsx
import React from "react";
import { Link } from "react-router-dom";
import { RESOURCES } from "../../../data/launchData.js";
import Section from "../Section.jsx";

export default function ResourcesSection() {
  return (
    <Section
      id="resources"
      title="Resources"
      subtitle="Explore practice libraries, guides, and platform status."
    >
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4 md:gap-6">
        {RESOURCES.map((r, i) => (
          <Link
            key={r.to}
            to={r.to}
            className="group relative rounded-2xl border border-transparent
                       bg-white/5 p-5 overflow-hidden
                       transition duration-200
                       focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-300/70
                       hover:-translate-y-[2px]"
            style={{
              /* pretty gradient border without extra wrappers */
              background:
                "linear-gradient(#11182780,#11182780) padding-box," +
                "linear-gradient(135deg, rgba(255, 255, 255, 0.35), rgba(1, 100, 248, 0.35)) border-box",
            }}
          >
            {/* Spotlight glow */}
            <span
              aria-hidden
              className="pointer-events-none absolute -top-16 -right-16 h-40 w-40 rounded-full blur-2xl opacity-25
                         transition group-hover:opacity-40"
              style={{
                background:
                  "radial-gradient(closest-side, rgba(147,197,253,.7), rgba(147,197,253,0))",
              }}
            />

            {/* Content */}
            <div className="relative flex items-center gap-3 mb-2">
              <span
                className="inline-grid h-11 w-11 place-items-center rounded-xl
                           bg-gradient-to-br from-blue-400/20 to-emerald-300/20
                           ring-1 ring-white/20 shadow-[inset_0_1px_0_rgba(255,255,255,.06)]"
              >
                <span className="text-[1.25rem] leading-none">{r.icon}</span>
              </span>

              <h4 className="text-[1.125rem] font-semibold tracking-tight">
                {r.label}
              </h4>
            </div>

            <p className="relative text-white/75 text-sm mb-4 min-h-[1.5rem]">
              {r.meta}
            </p>

            <span
              className="relative inline-flex items-center justify-center px-3 py-1.5 rounded-full
                         text-gray-900 font-semibold text-[0.9rem]
                         bg-gradient-to-r from-blue-400 via-blue-300 to-blue-400
                         transition shadow-sm
                         group-hover:from-blue-300 group-hover:via-blue-400 group-hover:to-blue-500"
            >
              Explore →
            </span>

            {/* subtle interactive glow on hover */}
            <span
              aria-hidden
              className="pointer-events-none absolute inset-0 rounded-2xl opacity-0
                         group-hover:opacity-100 transition"
              style={{
                boxShadow: "0 0 0 1px rgba(147,197,253,.35), 0 0 22px rgba(147,197,253,.22)",
              }}
            />
          </Link>
        ))}
      </div>

      {/* Local cosmetics specific to these cards */}
      <style>{`
        /* Sharper rendering on Windows/low-DPI */
        #resources a { -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
      `}</style>
    </Section>
  );
}
