// src/components/SignUpModal.jsx
import React, { useEffect, useState } from 'react';
import { useAuth } from '../AuthContext.jsx';
import { validatePassword } from '../utils/password.js';
import AuthLogo from './AuthLogo.jsx';

const SignUpModal = ({ isOpen, onClose, onSwitchToSignIn, onSuccess }) => {
  const { signUp } = useAuth();

  const [fullName, setFullName] = useState('');
  const [username, setUsername] = useState('');
  const [email, setEmail]       = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm]   = useState('');
  const [showPwd, setShowPwd] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [err, setErr] = useState('');
  const [strength, setStrength] = useState('');

  useEffect(() => {
    setStrength(password ? validatePassword(password) : '');
  }, [password]);

  if (!isOpen) return null;

  const submit = (e) => {
    e.preventDefault();
    if (!fullName || !username || !email || !password) return setErr('Please fill in all fields');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return setErr('Please enter a valid email address');
    if (validatePassword(password) !== 'Password is strong') return setErr('Please meet the password requirements.');
    if (password !== confirm) return setErr('Passwords do not match.');
    const ok = signUp(username, password, fullName, email);
    if (!ok) return setErr('Sign-up failed unexpectedly');
    setErr('');
    onSuccess?.(); // ✅ tell parent to navigate to pendingPath
    onClose?.();
  };

  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-slate-950/60 backdrop-blur-sm">
      <div className="bg-white/95 backdrop-blur-md p-6 md:p-8 rounded-3xl shadow-2xl border border-slate-100 max-w-md w-full mx-4 relative">
        <button onClick={onClose} aria-label="Close modal"
          className="absolute top-3 right-3 w-9 h-9 grid place-items-center rounded-full bg-white/80 hover:bg-white shadow border border-slate-200 text-slate-600">✕</button>

        <AuthLogo size={96} />

        <form onSubmit={submit}>
          <h2 className="text-2xl font-semibold text-slate-900 mb-1 text-center">Create your account</h2>
          <p className="text-sm text-slate-600 mb-5 text-center">Join TutorSimula in seconds</p>

          <div className="mb-4"><input type="text" placeholder="Full Name" value={fullName} onChange={(e)=>setFullName(e.target.value)}
            className="w-full h-11 px-4 rounded-xl bg-white text-slate-900 placeholder-slate-400 ring-1 ring-slate-200 focus:ring-2 focus:ring-sky-400/60 focus:outline-none shadow-inner transition"/></div>
          <div className="mb-4"><input type="text" placeholder="Username" value={username} onChange={(e)=>setUsername(e.target.value)}
            className="w-full h-11 px-4 rounded-xl bg-white text-slate-900 placeholder-slate-400 ring-1 ring-slate-200 focus:ring-2 focus:ring-sky-400/60 focus:outline-none shadow-inner transition"/></div>
          <div className="mb-4"><input type="email" placeholder="Email" value={email} onChange={(e)=>setEmail(e.target.value)}
            className="w-full h-11 px-4 rounded-xl bg-white text-slate-900 placeholder-slate-400 ring-1 ring-slate-200 focus:ring-2 focus:ring-sky-400/60 focus:outline-none shadow-inner transition"/></div>

          <div className="mb-2 relative">
            <input type={showPwd ? 'text' : 'password'} placeholder="Password" value={password} onChange={(e)=>setPassword(e.target.value)}
              className="w-full h-11 pr-20 px-4 rounded-xl bg-white text-slate-900 placeholder-slate-400 ring-1 ring-slate-200 focus:ring-2 focus:ring-sky-400/60 focus:outline-none shadow-inner transition"/>
            <button type="button" onClick={()=>setShowPwd((v)=>!v)}
              className="absolute right-2 top-1/2 -translate-y-1/2 text-xs font-medium px-3 py-1 rounded-md bg-slate-100 hover:bg-slate-200 text-slate-700">
              {showPwd ? 'Hide' : 'Show'}
            </button>
          </div>

          {password && strength !== 'Password is strong' && (
            <p className="text-xs text-red-600 mt-1">Password must be at least 8 characters and include at least one uppercase letter, one number, and one special character.</p>
          )}
          {password && /^[0-9]/.test(password) && (
            <p className="text-xs text-red-600 mt-1">Starting character should be an alphabet.</p>
          )}

          <div className="mt-3 relative">
            <input type={showConfirm ? 'text' : 'password'} placeholder="Confirm Password" value={confirm} onChange={(e)=>setConfirm(e.target.value)}
              className="w-full h-11 pr-20 px-4 rounded-xl bg-white text-slate-900 placeholder-slate-400 ring-1 ring-slate-200 focus:ring-2 focus:ring-sky-400/60 focus:outline-none shadow-inner transition"/>
            <button type="button" onClick={()=>setShowConfirm((v)=>!v)}
              className="absolute right-2 top-1/2 -translate-y-1/2 text-xs font-medium px-3 py-1 rounded-md bg-slate-100 hover:bg-slate-200 text-slate-700">
              {showConfirm ? 'Hide' : 'Show'}
            </button>
          </div>

          {!!confirm && confirm !== password && (
            <p className="text-xs text-red-600 mt-1">Passwords do not match.</p>
          )}

          {err && <p className="text-red-600 text-sm mb-3 text-center">{err}</p>}

          <div className="flex justify-center gap-3">
            <button type="submit"
              className="w-full h-11 rounded-xl bg-gradient-to-r from-indigo-600 to-sky-500 text-white font-semibold shadow-lg shadow-sky-500/20 hover:from-indigo-500 hover:to-sky-400 focus:outline-none focus:ring-2 focus:ring-sky-400/60">
              Sign Up
            </button>
            <button type="button" onClick={onClose}
              className="h-11 px-4 rounded-xl bg-slate-200 text-slate-700 hover:bg-slate-300">
              Cancel
            </button>
          </div>

          <hr className="my-6 border-slate-200/70" />
          <p className="text-slate-600 text-sm text-center">
            Already a Registered Member?{' '}
            <button onClick={onSwitchToSignIn} type="button" className="text-sky-600 hover:text-sky-700 underline-offset-2 hover:underline">Sign In</button>
          </p>
        </form>
      </div>
    </div>
  );
};

export default SignUpModal;
