// src/components/launch/sections/ServicesSection.jsx
import React from "react";
import { SERVICES } from "../../../data/launchData.js";
import Section from "../Section.jsx";

function CTA({ to = "/contact", label = "Talk to us" }) {
  return (
    <a
      href={to}
      className="inline-flex items-center px-3 py-1.5 rounded-full
                 bg-gradient-to-r from-blue-400 via-blue-300 to-blue-400
                 hover:from-blue-300 hover:via-blue-400 hover:to-blue-500
                 text-black font-semibold text-sm transition
                 focus:outline-none focus:ring-2 focus:ring-blue-300/70
                 focus:ring-offset-2 focus:ring-offset-transparent"
      aria-label={label}
    >
      {label}
      <span className="ml-1">→</span>
    </a>
  );
}

/** Centered service card with soft blue glow */
function ServiceCard({ item }) {
  return (
    <div
      className="service-card rounded-2xl bg-white/8 border border-white/10 px-6 py-6
                 min-h-[160px] flex flex-col items-center text-center
                 transition hover:bg-white/10 focus-within:bg-white/12"
      role="article"
    >
      {/* Icon in a soft circle */}
      <div className="mb-3 inline-flex h-10 w-10 items-center justify-center rounded-full bg-white/10 ring-1 ring-white/10 text-xl select-none">
        {item.icon ?? "✨"}
      </div>

      <h5 className="text-lg font-semibold">{item.label}</h5>

      {item.desc && (
        <p className="mt-2 text-white/75 max-w-[44ch]">{item.desc}</p>
      )}

      {/* Optional bullets (if item.bullets exists) */}
      {Array.isArray(item.bullets) && item.bullets.length > 0 && (
        <ul className="mt-3 space-y-1 text-sm text-white/75">
          {item.bullets.map((b) => (
            <li key={b} className="before:content-['•'] before:mr-2 before:text-white/60">
              {b}
            </li>
          ))}
        </ul>
      )}

      <div className="mt-4">
        <CTA to={item.to} />
      </div>
    </div>
  );
}

export default function ServicesSection() {
  return (
    <Section id="services">
      {/* Custom centered heading & subtitle */}
      <div className="text-center mb-8 md:mb-10">
        <h2 className="text-3xl md:text-5xl font-extrabold tracking-tight">
          <span className="bg-gradient-to-r from-blue-300 via-white to-blue-300 bg-clip-text text-transparent">
            Services
          </span>
        </h2>
        <p className="mt-2 text-white/75 text-sm md:text-base">
          Solutions for institutions and hiring teams.
        </p>
        <div className="mx-auto mt-5 h-[2px] w-28 md:w-36 bg-gradient-to-r from-transparent via-blue-300 to-transparent rounded-full" />
      </div>

      <div className="mx-auto max-w-6xl px-3 sm:px-4">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5 md:gap-6 items-stretch">
          {SERVICES.map((s) => (
            <ServiceCard key={s.to ?? s.label} item={s} />
          ))}
        </div>
      </div>

      {/* Gentle blue glow + lift */}
      <style>{`
        .service-card {
          transform: translateY(0);
          box-shadow: 0 0 0 rgba(59, 130, 246, 0); /* blue-500 */
        }
        .service-card:hover,
        .service-card:focus-within {
          transform: translateY(-2px);
          box-shadow: 0 0 18px rgba(59, 130, 246, 0.25);
          border-color: rgba(59, 130, 246, 0.38);
        }
      `}</style>
    </Section>
  );
}
