// src/App.jsx
import React, { Suspense, lazy } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import './App.css';

// Core pages
import LaunchPage from './pages/LaunchPage.jsx';
import InterviewQuestionsHub from './pages/InterviewQuestionsHub.jsx';
import CompanyInterviewHub from './pages/CompanyInterviewHub.jsx';

// Lazy pages (existing)
const AboutPage           = lazy(() => import('./components/AboutPage.jsx'));
const ProgramsPage        = lazy(() => import('./components/ProgramsPage.jsx'));
const HelpPage            = lazy(() => import('./components/HelpPage.jsx'));
const ProfilePage         = lazy(() => import('./components/ProfilePage.jsx'));
const CodeEditorPage      = lazy(() => import('./components/CodeEditorPage.jsx'));
const ProtectedRoute      = lazy(() => import('./components/ProtectedRoute.jsx'));
const MockInterviewComp   = lazy(() => import('./components/MockInterviewComponent.jsx'));
const TechnologySelection = lazy(() => import('./components/TechnologySelection.jsx'));
const TermsAndConditions  = lazy(() => import('./components/TermsAndConditions.jsx'));
const ResumeUpload        = lazy(() => import('./components/ResumeUpload.jsx'));
const StagesInformation   = lazy(() => import('./components/StagesInformation.jsx'));
const InterviewRoom       = lazy(() => import('./pages/InterviewRoom.jsx'));

// Generic stubs (keep for other areas)
const GenericStub = lazy(() => import('./pages/stubs/GenericStub.jsx'));
const SlugStub    = lazy(() => import('./pages/stubs/SlugStub.jsx'));

function SummaryPage() {
  const url = (() => { try { return localStorage.getItem('interview.lastBlobUrl'); } catch { return null; } })();
  return (
    <div className="min-h-screen bg-gray-800 text-white pt-20 px-3 md:px-6">
      <h1 className="text-3xl font-bold mb-4">Session Summary</h1>
      <p className="text-white/80 mb-6">Detailed insights coming soon.</p>
      {url && (
        <a
          href={url}
          download="interview.webm"
          className="inline-block px-4 py-2 rounded-lg bg-green-500 text-gray-900 font-semibold"
        >
          Download Recording
        </a>
      )}
    </div>
  );
}

export default function App() {
  return (
    <div className="min-h-screen bg-gray-800 text-white">
      <Suspense fallback={<div className="p-6">Loading…</div>}>
        <Routes>
          {/* Core */}
          <Route path="/" element={<LaunchPage />} />
          <Route path="/about" element={<AboutPage />} />
          <Route path="/programs" element={<ProgramsPage />} />
          <Route path="/help" element={<HelpPage />} />
          <Route path="/profile" element={<ProtectedRoute><ProfilePage /></ProtectedRoute>} />
          <Route path="/profile/:program" element={<ProtectedRoute><ProfilePage /></ProtectedRoute>} />
          <Route path="/code-editor" element={<ProtectedRoute><CodeEditorPage /></ProtectedRoute>} />
          <Route path="/technology-selection" element={<TechnologySelection />} />
          <Route path="/terms-and-conditions" element={<TermsAndConditions />} />
          <Route path="/resume-upload" element={<ResumeUpload />} />
          <Route path="/stages-information" element={<StagesInformation />} />
          <Route path="/interview" element={<InterviewRoom />} />
          <Route path="/summary" element={<SummaryPage />} />

          {/* Mock Interview entry points */}
          <Route path="/profile/mock-interview" element={<MockInterviewComp />} />
          <Route path="/mock-interview" element={<MockInterviewComp />} />

          {/* ===== MockInterviews mega-menu routes ===== */}
          <Route path="/interviews/position/:slug" element={<SlugStub prefix="Position Interview" />} />
          {/* ✅ Use the REAL Company Interview Hub */}
          <Route path="/interviews/company/:slug" element={<CompanyInterviewHub />} />
          <Route path="/interviews/other/:slug" element={<SlugStub prefix="Interview Type" />} />
          <Route path="/interviews/tracks/:slug" element={<SlugStub prefix="Track" />} />

          {/* ===== Products ===== */}
          <Route path="/resume-builder" element={<GenericStub title="Resume Builder" />} />
          <Route path="/resume-analyzer" element={<GenericStub title="Resume Analyzer" />} />
          <Route path="/avatar-quick-mock" element={<GenericStub title="5-min Avatar Mock" />} />
          <Route path="/question-of-the-day" element={<GenericStub title="Question of the Day" />} />
          <Route path="/task-of-the-day" element={<GenericStub title="Task of the Day" />} />

          {/* ===== Services ===== */}
          <Route path="/for-colleges" element={<GenericStub title="For Colleges" />} />
          <Route path="/for-recruiters" element={<GenericStub title="For Recruiters" />} />
          <Route path="/for-schools" element={<GenericStub title="For Schools" />} />

          {/* ===== Resources ===== */}
          <Route path="/interview-questions" element={<InterviewQuestionsHub />} />
          <Route path="/coding-problems" element={<GenericStub title="Coding Problems" />} />
          <Route path="/articles" element={<GenericStub title="Articles" />} />
          <Route path="/faq" element={<GenericStub title="FAQs" />} />
          <Route path="/status" element={<GenericStub title="Status" />} />

          {/* ===== Company / Marketing ===== */}
          <Route path="/careers" element={<GenericStub title="Careers" />} />
          <Route path="/blog" element={<GenericStub title="Blog" />} />
          <Route path="/contact" element={<GenericStub title="Contact" />} />
          <Route path="/pricing" element={<GenericStub title="Pricing" />} />

          {/* Catch-all */}
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Suspense>
    </div>
  );
}
