// src/pages/LaunchPage.jsx
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

import NavBar from "../NavBar.jsx";
import Chatbot from "../components/Chatbot.jsx";
import SuccessStories from "../components/SuccessStories.jsx";
import Footer from "../components/Footer.jsx";
import SignInModal from "../components/SignInModal.jsx";
import SignUpModal from "../components/SignUpModal.jsx";
import ForgotPasswordModal from "../components/ForgotPasswordModal.jsx";
import ForgotUsernameModal from "../components/ForgotUsernameModal.jsx";

import successStories from "../data/successStories.js";
import { useAuth } from "../AuthContext.jsx";

// New split components
import Hero from "../components/launch/Hero.jsx";

import MockInterviewsSection from "../components/launch/sections/MockInterviewsSection.jsx";
import ProductsSection from "../components/launch/sections/ProductsSection.jsx";
import ServicesSection from "../components/launch/sections/ServicesSection.jsx";
import ResourcesSection from "../components/launch/sections/ResourcesSection.jsx";
import CompanySection from "../components/launch/sections/CompanySection.jsx";
import PricingSection from "../components/launch/sections/PricingSection.jsx";
import ProgramIntroSections from "../components/launch/ProgramIntroSections.jsx";
const LaunchPage = () => {
  const navigate = useNavigate();
  const { user } = useAuth();

  // 'signin' | 'signup' | 'forgot' | 'forgot-username' | null
  const [modal, setModal] = useState(null);
  const [isChatbotOpen, setIsChatbotOpen] = useState(false);
  const toggleChatbot = () => setIsChatbotOpen((v) => !v);

  const handleStart = () => {
    if (user) navigate("/mock-interview");
    else setModal("signup");
  };

  return (
    <div className="min-h-screen bg-gray-800 text-white flex flex-col overflow-x-hidden"
  style={{ scrollBehavior: "smooth" }}
>
      {/* Top Nav */}
      <NavBar onSignIn={() => setModal("signin")} onSignUp={() => setModal("signup")} />

      {/* Hero */}
      <Hero onStart={handleStart} />

      <ProgramIntroSections />

      {/* Sections that mirror all NavBar content */}
      <MockInterviewsSection />
      <ProductsSection />
      <ServicesSection />
      <ResourcesSection />
      <CompanySection />
      <PricingSection />

      {/* Keep your existing highlights below (optional — they add credibility) */}
      <section className="w-full py-12 md:py-16">
        <div className="w-full px-3 md:px-6">
          <h2 className="text-2xl md:text-3xl font-bold text-white mb-6 md:mb-10">Success Stories</h2>
          <div className="w-full px-0">
            <SuccessStories stories={successStories} />
          </div>
        </div>
      </section>

      {/* Auth Modals */}
      <SignInModal
        isOpen={modal === "signin"}
        onClose={() => setModal(null)}
        onSwitchToSignUp={() => setModal("signup")}
        onSwitchToForgot={() => setModal("forgot")}
        onSwitchToForgotUsername={() => setModal("forgot-username")}
      />
      <SignUpModal
        isOpen={modal === "signup"}
        onClose={() => setModal(null)}
        onSwitchToSignIn={() => setModal("signin")}
      />
      <ForgotPasswordModal
        isOpen={modal === "forgot"}
        onClose={() => setModal(null)}
        onBack={() => setModal("signin")}
      />
      <ForgotUsernameModal
        isOpen={modal === "forgot-username"}
        onClose={() => setModal(null)}
        onBack={() => setModal("signin")}
      />

      {/* Chatbot + Footer */}
      <Chatbot isOpen={isChatbotOpen} toggleChatbot={toggleChatbot} />
      <Footer />

      {/* Animations (kept from your page) */}
      <style>{`
        @keyframes swirlIn {
          0% { transform: rotate(90deg) scale(0); opacity: 0; }
          50% { transform: rotate(0deg) scale(1.1); opacity: 0.5; }
          100% { transform: rotate(0deg) scale(1); opacity: 1; }
        }
        @keyframes heartbeat {
          0% { transform: scale(1); }
          10% { transform: scale(1.05); }
          20% { transform: scale(1); }
          30% { transform: scale(1.03); }
          40% { transform: scale(1); }
          100% { transform: scale(1); }
        }
        @keyframes glowPulse {
          0%   { box-shadow: 0 0 0px 0 rgba(74, 222, 128, 0.30); }
          50%  { box-shadow: 0 0 22px 6px rgba(74, 222, 128, 0.75); }
          100% { box-shadow: 0 0 0px 0 rgba(74, 222, 128, 0.30); }
        }
        .animate-logo { animation: swirlIn 1.5s ease-out forwards; }
        .animate-heartbeat { animation: heartbeat 2.5s ease-in-out infinite; }
        .glow-card { animation: glowPulse 2.4s ease-in-out infinite; border-color: rgba(74, 222, 128, 0.55); }
        @media (prefers-reduced-motion: no-preference) {
          .animate-logo { animation: swirlIn 1.5s ease-out forwards; }
          .animate-heartbeat { animation: heartbeat 2.5s ease-in-out infinite; }
        }
      `}</style>
    </div>
  );
};

export default LaunchPage;
