import React from "react";
import tutorsimulaLogo from "../../assets/tutorsimula-logo-purple.png";

export default function Hero({ onStart }) {
  return (
    <section className="w-full py-14 md:py-20">
      <div className="w-full px-3 md:px-6">
        <div className="text-center">
          <img
            src={tutorsimulaLogo}
            alt="TutorSimula Logo"
            className="w-40 md:w-56 h-auto mx-auto mb-6 animate-logo animate-heartbeat"
            onError={(e) => {
              e.currentTarget.src =
                "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";
            }}
          />
          <h1 className="text-3xl md:text-5xl font-extrabold leading-tight">
            Master Technical Interviews with AI-Powered Practice
          </h1>
          <p className="mt-3 text-lg md:text-xl text-white/90">
            Personalized mock interviews, real-time feedback, and a pro setup.
          </p>
          <p className="mt-1 text-base md:text-lg text-white/80">Start your professional journey today.</p>
          <div className="mt-8 flex items-center justify-center gap-3 flex-wrap">
            
          </div>
        </div>
      </div>
    </section>
  );
}
