// src/components/launch/sections/CompanySection.jsx
import React from "react";
import { COMPANY_LINKS } from "../../../data/launchData.js";
import Section from "../Section.jsx";
import LinkCard from "../cards/LinkCard.jsx";

export default function CompanySection() {
  return (
    <Section id="company" title="Company" subtitle="Learn about TutorSimula and how we can help you grow.">
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4 md:gap-6">
        {COMPANY_LINKS.map((c) => (
          <LinkCard key={c.to} to={c.to} title={c.label} icon={c.icon} desc={c.desc} />
        ))}
      </div>
    </Section>
  );
}
