// src/components/SuccessStories.jsx
import React from 'react';
import Slider from 'react-slick';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';

const fallbackSVG = (text = 'User') =>
  `data:image/svg+xml;utf8,` +
  encodeURIComponent(
    `<svg xmlns="http://www.w3.org/2000/svg" width="150" height="150">
      <rect width="100%" height="100%" fill="#e2e8f0"/>
      <text x="50%" y="50%" dominant-baseline="middle" text-anchor="middle"
            font-family="Arial,sans-serif" font-size="20" fill="#334155">${text}</text>
    </svg>`
  );

const SuccessStories = ({ stories = [] }) => {
  const settings = {
    dots: true, infinite: true, speed: 500,
    slidesToShow: 3, slidesToScroll: 1,
    autoplay: true, autoplaySpeed: 3000, cssEase: 'linear', rtl: true,
    responsive: [{ breakpoint: 1024, settings: { slidesToShow: 2 } }, { breakpoint: 640, settings: { slidesToShow: 1 } }],
  };

  const srcFor = (story) => {
    const first = (story?.name || 'User').split(' ')[0];
    // If no photo or known-blocked host, use inline SVG (no network)
    if (!story?.photo || /via\.placeholder\.com/i.test(story.photo)) {
      return fallbackSVG(first);
    }
    return story.photo;
  };

  return (
    <div id="testimonials" className="py-16 text-center rounded-lg mb-12">
      <h2 className="text-3xl font-bold text-white mb-8">Success Stories</h2>
      <Slider {...settings}>
        {stories.map((story, i) => {
          const first = (story?.name || 'User').split(' ')[0];
          return (
            <div key={i} className="p-4">
              <div className="bg-white rounded-2xl shadow-xl border border-gray-100 h-[320px] md:h-[340px] flex flex-col items-center text-center">
                <img
                  src={srcFor(story)}
                  alt={story?.name || 'User'}
                  className="w-24 h-24 rounded-full mt-6 object-cover"
                  loading="lazy"
                  // If an external URL still fails, fall back to SVG
                  onError={(e) => { e.currentTarget.src = fallbackSVG(first); }}
                />
                <div className="px-4 pt-3 pb-4 flex-1 flex flex-col w-full">
                  <h3 className="text-lg font-semibold text-slate-900">{story.name}</h3>
                  <p className="text-slate-700 mt-1">{story.achievement}</p>
                  <blockquote className="mt-auto text-slate-500 italic">"{story.quote}"</blockquote>
                </div>
              </div>
            </div>
          );
        })}
      </Slider>
    </div>
  );
};

export default SuccessStories;
