// src/NavBar.jsx
import React, { useRef, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "./AuthContext.jsx";
import tutorsimulaLogo from "./assets/tutorsimula-logo-purple.png";

// ✅ Modals for auth gating
import SignInModal from "./components/SignInModal.jsx";
import SignUpModal from "./components/SignUpModal.jsx";

export default function NavBar() {
  const { user, signOut } = useAuth();
  const navigate = useNavigate();

  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [openDesktopMenu, setOpenDesktopMenu] = useState(null);
  const [openMobile, setOpenMobile] = useState({
    mock: false, products: false, services: false, resources: false, company: false,
  });

  // Auth-gate modal state
  const [showSignIn, setShowSignIn] = useState(false);
  const [showSignUp, setShowSignUp] = useState(false);
  const [pendingPath, setPendingPath] = useState(null);

  // hover-intent debounce so dropdowns don’t vanish on mouse travel
  const closeTimerRef = useRef(null);
  const clearCloseTimer = () => { if (closeTimerRef.current) { clearTimeout(closeTimerRef.current); closeTimerRef.current = null; } };
  const scheduleClose = () => { clearCloseTimer(); closeTimerRef.current = setTimeout(() => setOpenDesktopMenu(null), 180); };
  const openMenu = (id) => { clearCloseTimer(); setOpenDesktopMenu(id); };

  const toggleMenu = () => setIsMenuOpen((v) => !v);

  const handleSignOut = () => { signOut(); navigate("/"); };

  // ============ AUTH GATE ============
  const requireAuthNavigate = (to) => {
    if (user) {
      navigate(to);
    } else {
      setPendingPath(to || "/");
      setShowSignIn(true); // default to Sign In, user can switch to Sign Up
    }
  };

  const handleAuthSuccess = () => {
    const dest = pendingPath || "/";
    setShowSignIn(false);
    setShowSignUp(false);
    setPendingPath(null);
    navigate(dest);
  };

  // ============ DATA (menus) ============
  const MI_POSITIONS = [
    { label: "Frontend Engineer",                     to: "/interviews/position/frontend-engineer" },
    { label: "Backend Engineer",                      to: "/interviews/position/backend-engineer" },
    { label: "Full-Stack Developer",                  to: "/interviews/position/full-stack-developer" },
    { label: "Algorithms & Data Structures (DSA)",    to: "/interviews/position/algorithms-and-data-structures" },
    { label: "Data Analyst",                          to: "/interviews/position/data-analyst" },
    { label: "Machine Learning Engineer",             to: "/interviews/position/machine-learning-engineer" },
    { label: "Data Scientist",                        to: "/interviews/position/data-scientist" },
    { label: "DevOps Engineer",                       to: "/interviews/position/devops-engineer" },
    { label: "Cloud Engineer (Cloud Computing Engineer)", to: "/interviews/position/cloud-engineer" },
  ];

  const MI_COMPANIES = [
    { label: "Amazon",    to: "/interviews/company/amazon" },
    { label: "Apple",     to: "/interviews/company/apple" },
    { label: "Google",    to: "/interviews/company/google" },
    { label: "Meta",      to: "/interviews/company/meta" },
    { label: "Netflix",   to: "/interviews/company/netflix" },
    { label: "Microsoft", to: "/interviews/company/microsoft" },
  ];

  const MI_OTHERS = [
    { label: "Behavioral (STAR)",  to: "/interviews/other/behavioral" },
    { label: "System Design",      to: "/interviews/other/system-design" },
    { label: "DSA / Algorithms",   to: "/interviews/other/dsa" },
    { label: "SQL & Data Modeling",to: "/interviews/other/sql" },
    { label: "Aptitude & Logic",   to: "/interviews/other/aptitude" },
    { label: "HR Round",           to: "/interviews/other/hr" },
  ];

  const MI_MORE = [
    { label: "Service-based Tracks", to: "/interviews/tracks/service-based" },
    { label: "Product-based Tracks", to: "/interviews/tracks/product-based" },
    { label: "Startup Tracks",       to: "/interviews/tracks/startup" },
  ];

  const PRODUCTS = [
    { to: "/resume-builder",      label: "Resume Builder" },
    { to: "/resume-analyzer",     label: "Resume Analyzer" },
    { to: "/avatar-quick-mock",   label: "5-min Avatar Mock" },
    { to: "/question-of-the-day", label: "Question of the Day" },
    { to: "/task-of-the-day",     label: "Task of the Day" },
  ];

  const SERVICES = [
    { to: "/for-colleges",   label: "For Colleges" },
    { to: "/for-recruiters", label: "For Recruiters" },
    { to: "/for-schools",    label: "For Schools" },
  ];

  const RESOURCES = [
    { to: "/interview-questions", label: "Interview Questions" },
    { to: "/coding-problems",     label: "Coding Problems" },
    { to: "/articles",            label: "Articles" },
    { to: "/faq",                 label: "FAQs" },
    { to: "/status",              label: "Status" },
  ];

  const COMPANY = [
    { to: "/programs", label: "Programs" },
    { to: "/about",    label: "About" },
    { to: "/careers",  label: "Careers" },
    { to: "/blog",     label: "Blog" },
    { to: "/contact",  label: "Contact" },
  ];

  // ============ UI PARTS ============
  const GuardedLink = ({ to, className, children, onAfter }) => (
    <a
      href={to}
      className={className}
      onClick={(e) => {
        e.preventDefault();
        onAfter?.(); // e.g., close mobile menu
        requireAuthNavigate(to);
      }}
    >
      {children}
    </a>
  );

  const Drop = ({ id, label, items }) => (
    <div className="relative">
      <button
        className="text-gray-200 hover:text-white px-3 py-2 rounded-md text-sm font-medium inline-flex items-center gap-1"
        aria-haspopup="true"
        aria-expanded={openDesktopMenu === id}
        onMouseEnter={() => openMenu(id)}
        onMouseLeave={scheduleClose}
        onFocus={() => openMenu(id)}
      >
        {label}
        <svg className={`h-4 w-4 transition-transform ${openDesktopMenu === id ? "rotate-180" : ""}`} viewBox="0 0 20 20" fill="currentColor">
          <path d="M5.23 7.21a.75.75 0 011.06.02L10 10.94l3.71-3.71a.75.75 0 111.06 1.06l-4.24 4.24a.75.75 0 01-1.06 0L5.21 8.29a.75.75 0 01.02-1.08z" />
        </svg>
      </button>

      {openDesktopMenu === id && (
        <div
          className="absolute left-0 top-full translate-y-2 w-56 rounded-lg border border-white/10 bg-gray-800 shadow-xl p-2 z-[60]"
          onMouseEnter={() => openMenu(id)}
          onMouseLeave={scheduleClose}
        >
          {items.map((it) => (
            <GuardedLink
              key={it.to}
              to={it.to}
              className="block px-3 py-2 rounded-md text-sm text-gray-200 hover:text-white hover:bg-white/10"
            >
              {it.label}
            </GuardedLink>
          ))}
        </div>
      )}
    </div>
  );

  const MegaDrop = ({ id, label, sections }) => (
    <div className="relative">
      <button
        className="text-gray-200 hover:text-white px-3 py-2 rounded-md text-sm font-medium inline-flex items-center gap-1"
        aria-haspopup="true"
        aria-expanded={openDesktopMenu === id}
        onMouseEnter={() => openMenu(id)}
        onMouseLeave={scheduleClose}
        onFocus={() => openMenu(id)}
      >
        {label}
        <svg className={`h-4 w-4 transition-transform ${openDesktopMenu === id ? "rotate-180" : ""}`} viewBox="0 0 20 20" fill="currentColor">
          <path d="M5.23 7.21a.75.75 0 011.06.02L10 10.94l3.71-3.71a.75.75 0 111.06 1.06l-4.24 4.24a.75.75 0 01-1.06 0L5.21 8.29a.75.75 0 01.02-1.08z" />
        </svg>
      </button>

      {openDesktopMenu === id && (
        <div
          className="absolute left-0 top-full translate-y-2 w-[780px] max-w-[92vw] rounded-xl border border-white/10 bg-gray-800 shadow-2xl p-4 z-[70]"
          onMouseEnter={() => openMenu(id)}
          onMouseLeave={scheduleClose}
        >
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {sections.map((sec) => (
              <div key={sec.title}>
                <div className="text-white font-semibold text-sm mb-2">{sec.title}</div>
                <div className="flex flex-col gap-1">
                  {sec.items.map((it) => (
                    <GuardedLink
                      key={it.to}
                      to={it.to}
                      className="text-gray-200 hover:text-white hover:bg-white/10 rounded-md px-2 py-1 text-sm"
                    >
                      {it.label}
                    </GuardedLink>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );

  return (
    <>
      <nav className="fixed top-0 w-full bg-gray-900/95 backdrop-blur supports-[backdrop-filter]:bg-gray-900/75 z-50 border-b border-white/10">
        <div className="px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            {/* Logo (guarded) */}
            <div className="flex-shrink-0 flex items-center">
              <GuardedLink to="/" className="flex items-center">
                <img
                  src={tutorsimulaLogo}
                  alt="TutorSimula Logo"
                  className="h-7 w-auto mr-2"
                  onError={(e) => {
                    e.currentTarget.src =
                      "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";
                  }}
                />
                <span className="text-xl font-bold text-white">TutorSimula</span>
              </GuardedLink>
            </div>

            {/* Desktop nav */}
            <div className="hidden md:flex items-center gap-1">
              <GuardedLink to="/" className="text-gray-200 hover:text-white px-3 py-2 rounded-md text-sm font-medium">Home</GuardedLink>

              {/* MockInterviews mega menu */}
              <MegaDrop
                id="mock"
                label="MockInterviews"
                sections={[
                  { title: "By Position",      items: MI_POSITIONS },
                  { title: "By Company",       items: MI_COMPANIES },
                  { title: "Other Interviews", items: MI_OTHERS },
                  { title: "More",             items: MI_MORE },
                ]}
              />

              {/* Other menus */}
              <Drop id="products"  label="Products"  items={PRODUCTS} />
              <Drop id="services"  label="Services"  items={SERVICES} />
              <Drop id="resources" label="Resources" items={RESOURCES} />
              <Drop id="company"   label="Company"   items={COMPANY} />

              <GuardedLink to="/pricing" className="text-gray-200 hover:text-white px-3 py-2 rounded-md text-sm font-medium">Pricing</GuardedLink>

              {/* Auth (desktop) — explicit buttons still work */}
              {user ? (
                <button
                  type="button"
                  onClick={handleSignOut}
                  className="ml-2 bg-gradient-to-r from-red-600 to-red-800 text-white px-4 py-2 rounded-lg text-sm font-semibold hover:from-red-700 hover:to-red-900 transition"
                >
                  Sign Out
                </button>
              ) : (
                <div className="ml-2 flex gap-2">
                  <button
                    type="button"
                    onClick={() => setShowSignIn(true)}
                    className="bg-green-500 hover:bg-green-400 text-gray-900 px-4 py-2 rounded-lg text-sm font-semibold transition"
                  >
                    Sign In
                  </button>
                  <button
                    type="button"
                    onClick={() => setShowSignUp(true)}
                    className="bg-green-500 hover:bg-green-400 text-gray-900 px-4 py-2 rounded-lg text-sm font-semibold transition"
                  >
                    Sign Up
                  </button>
                </div>
              )}
            </div>

            {/* Mobile menu button */}
            <div className="md:hidden flex items-center">
              <button onClick={toggleMenu} className="text-gray-200 hover:text-white focus:outline-none" type="button" aria-label="Toggle menu">
                <svg className="h-7 w-7" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  {isMenuOpen ? (
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                  ) : (
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
                  )}
                </svg>
              </button>
            </div>
          </div>

          {/* Mobile menu */}
          {isMenuOpen && (
            <div className="md:hidden pb-3">
              <div className="px-2 pt-2 space-y-1">
                <GuardedLink to="/" onAfter={toggleMenu} className="block px-3 py-2 rounded-md text-base font-medium text-gray-200 hover:text-white hover:bg-white/10">Home</GuardedLink>

                {/* MockInterviews */}
                <div className="border border-white/10 rounded-md">
                  <button
                    className="w-full flex items-center justify-between px-3 py-2 text-left text-base font-medium text-gray-200 hover:text-white"
                    onClick={() => setOpenMobile((s) => ({ ...s, mock: !s.mock }))}
                    aria-expanded={openMobile.mock}
                  >
                    MockInterviews
                    <svg className={`h-5 w-5 transition-transform ${openMobile.mock ? "rotate-180" : ""}`} viewBox="0 0 20 20" fill="currentColor">
                      <path d="M5.23 7.21a.75.75 0 011.06.02L10 10.94l3.71-3.71a.75.75 0 111.06 1.06l-4.24 4.24a.75.75 0 01-1.06 0L5.21 8.29a.75.75 0 01.02-1.08z" />
                    </svg>
                  </button>
                  {openMobile.mock && (
                    <div className="px-2 pb-2 space-y-3">
                      <div>
                        <div className="text-white font-semibold text-sm mb-1">By Position</div>
                        {MI_POSITIONS.map((it) => (
                          <GuardedLink key={it.to} to={it.to} onAfter={toggleMenu} className="block px-3 py-2 rounded-md text-sm text-gray-200 hover:text-white hover:bg-white/10">
                            {it.label}
                          </GuardedLink>
                        ))}
                      </div>
                      <div>
                        <div className="text-white font-semibold text-sm mb-1">By Company</div>
                        {MI_COMPANIES.map((it) => (
                          <GuardedLink key={it.to} to={it.to} onAfter={toggleMenu} className="block px-3 py-2 rounded-md text-sm text-gray-200 hover:text-white hover:bg-white/10">
                            {it.label}
                          </GuardedLink>
                        ))}
                      </div>
                      <div>
                        <div className="text-white font-semibold text-sm mb-1">Other Interviews</div>
                        {MI_OTHERS.map((it) => (
                          <GuardedLink key={it.to} to={it.to} onAfter={toggleMenu} className="block px-3 py-2 rounded-md text-sm text-gray-200 hover:text-white hover:bg-white/10">
                            {it.label}
                          </GuardedLink>
                        ))}
                      </div>
                      <div>
                        <div className="text-white font-semibold text-sm mb-1">More</div>
                        {MI_MORE.map((it) => (
                          <GuardedLink key={it.to} to={it.to} onAfter={toggleMenu} className="block px-3 py-2 rounded-md text-sm text-gray-200 hover:text-white hover:bg-white/10">
                            {it.label}
                          </GuardedLink>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                {/* Other groups */}
                {[
                  { key: "products",  label: "Products",  items: PRODUCTS },
                  { key: "services",  label: "Services",  items: SERVICES },
                  { key: "resources", label: "Resources", items: RESOURCES },
                  { key: "company",   label: "Company",   items: COMPANY },
                ].map((section) => (
                  <div key={section.key} className="border border-white/10 rounded-md">
                    <button
                      className="w-full flex items-center justify-between px-3 py-2 text-left text-base font-medium text-gray-200 hover:text-white"
                      onClick={() => setOpenMobile((s) => ({ ...s, [section.key]: !s[section.key] }))}
                      aria-expanded={openMobile[section.key]}
                    >
                      {section.label}
                      <svg className={`h-5 w-5 transition-transform ${openMobile[section.key] ? "rotate-180" : ""}`} viewBox="0 0 20 20" fill="currentColor">
                        <path d="M5.23 7.21a.75.75 0 011.06.02L10 10.94l3.71-3.71a.75.75 0 111.06 1.06l-4.24 4.24a.75.75 0 01-1.06 0L5.21 8.29a.75.75 0 01.02-1.08z" />
                      </svg>
                    </button>
                    {openMobile[section.key] && (
                      <div className="px-2 pb-2">
                        {section.items.map((it) => (
                          <GuardedLink
                            key={it.to}
                            to={it.to}
                            onAfter={toggleMenu}
                            className="block px-3 py-2 rounded-md text-sm text-gray-200 hover:text-white hover:bg-white/10"
                          >
                            {it.label}
                          </GuardedLink>
                        ))}
                      </div>
                    )}
                  </div>
                ))}

                <GuardedLink to="/pricing" onAfter={toggleMenu} className="block px-3 py-2 rounded-md text-base font-medium text-gray-200 hover:text-white hover:bg-white/10">
                  Pricing
                </GuardedLink>

                {/* Auth (mobile) — explicit buttons */}
                {!user && (
                  <>
                    <button
                      type="button"
                      onClick={() => { setShowSignIn(true); toggleMenu(); }}
                      className="mt-1 bg-green-500 hover:bg-green-400 text-gray-900 block w-full text-left px-3 py-2 rounded-md text-base font-semibold transition"
                    >
                      Sign In
                    </button>
                    <button
                      type="button"
                      onClick={() => { setShowSignUp(true); toggleMenu(); }}
                      className="mt-1 bg-green-500 hover:bg-green-400 text-gray-900 block w-full text-left px-3 py-2 rounded-md text-base font-semibold transition"
                    >
                      Sign Up
                    </button>
                  </>
                )}
                {user && (
                  <button
                    type="button"
                    onClick={() => { handleSignOut(); toggleMenu(); }}
                    className="mt-1 bg-gradient-to-r from-red-600 to-red-800 text-white block w-full text-left px-3 py-2 rounded-md text-base font-medium hover:from-red-700 hover:to-red-900 transition"
                  >
                    Sign Out
                  </button>
                )}
              </div>
            </div>
          )}
        </div>
      </nav>

      {/* ===== Auth Modals with success callback (will blur background via backdrop) ===== */}
      <SignInModal
        isOpen={showSignIn}
        onClose={() => setShowSignIn(false)}
        onSwitchToSignUp={() => { setShowSignIn(false); setShowSignUp(true); }}
        onSwitchToForgot={() => {}}
        onSwitchToForgotUsername={() => {}}
        onSuccess={handleAuthSuccess}   // ✅ navigate to pendingPath after success
      />
      <SignUpModal
        isOpen={showSignUp}
        onClose={() => setShowSignUp(false)}
        onSwitchToSignIn={() => { setShowSignUp(false); setShowSignIn(true); }}
        onSuccess={handleAuthSuccess}   // ✅ navigate to pendingPath after success
      />
    </>
  );
}
