import React from "react";
import { Link } from "react-router-dom";

export default function LinkCard({
  to,
  title,
  desc,
  icon,
  badges,
  ctaLabel = "Explore →",
  logoSrc,
  logoAlt = title,
  hideTitle = false,
  className = "",          // NEW
}) {
  const hasLogo = !!logoSrc;

  return (
    <div className={`bg-white/10 border border-white/15 rounded-xl p-5 hover:bg-white/15 transition ${className}`}>
      <div className="flex items-start gap-3">
        {hasLogo ? (
          <div className="w-full flex items-center">
            <img
              src={logoSrc}
              alt={logoAlt}
              className="h-10 md:h-12 object-contain"
              loading="lazy"
            />
          </div>
        ) : (
          icon && <div className="text-2xl leading-none">{icon}</div>
        )}

        <div className={`${hasLogo ? "w-0 h-0 overflow-hidden sr-only" : ""}`}>
          {!hideTitle && (
            <div className="text-base md:text-lg font-semibold">{title}</div>
          )}
          {(hideTitle || hasLogo) && <span className="sr-only">{title}</span>}
          {desc && !hasLogo && <p className="text-white/75 mt-1">{desc}</p>}
        </div>
      </div>

      {badges && badges.length > 0 && (
        <div className="mt-2 flex flex-wrap gap-2">
          {badges.map((b) => (
            <span key={b} className="text-xs bg-white/10 border border-white/10 px-2 py-0.5 rounded">
              {b}
            </span>
          ))}
        </div>
      )}

      <div className="mt-4">
        <Link to={to} className="text-sm font-semibold underline underline-offset-4 hover:text-white">
          {ctaLabel}
        </Link>
      </div>
    </div>
  );
}
