// src/components/launch/sections/MockInterviewsSection.jsx
import React from "react";
import { Link } from "react-router-dom";
import { MI_POSITIONS, MI_COMPANIES } from "../../../data/launchData.js";
import Section from "../Section.jsx";

export default function MockInterviewsSection() {
  // Import all position GIFs from src/assets (keeps assets in src/)
  const GIF_URLS = React.useMemo(() => {
    const mods = import.meta.glob("../../../assets/position-gifs/*.gif", { eager: true, as: "url" });
    const map = {};
    for (const [path, url] of Object.entries(mods)) {
      const filename = path.split("/").pop() || "";
      const slug = filename.replace(/\.gif$/i, "");
      map[slug] = url;
    }
    return map;
  }, []);

  return (
    <Section >
      <div className="mx-auto max-w-6xl px-3 sm:px-4">

        {/* By Position — alternating GIF | Text (no cards) */}
        <div className="text-center mb-8 md:mb-10">
          <h3 className="text-3xl md:text-5xl font-extrabold tracking-tight">
            <span className="bg-gradient-to-r from-blue-300 via-white to-blue-300 bg-clip-text text-transparent">
              By Position
            </span>
          </h3>
          <p className="mt-3 text-white/75 text-sm md:text-base">
            Pick your target role and start practicing
          </p>
          <div className="mx-auto mt-5 h-[2px] w-28 md:w-36 bg-gradient-to-r from-transparent via-blue-400 to-transparent rounded-full" />
        </div>

        <div className="space-y-6 md:space-y-8">
          {MI_POSITIONS.map((it, idx) => {
            const isEven = idx % 2 === 0; // even rows: GIF left, text right
            const slug = it.to.split("/").pop();
            const gifSrc = GIF_URLS[slug];

            return (
              <Link
                key={it.to}
                to={it.to}
                className="group/row block rounded-2xl px-2 md:px-4 py-5 transition-colors hover:bg-white/[0.035]"
                aria-label={`Practice ${it.label}`}
                title={it.label}
              >
                <div className="grid md:grid-cols-12 items-center gap-6 md:gap-10">
                  {/* GIF */}
                  <div className={`md:col-span-5 ${isEven ? "" : "md:order-2"} flex justify-center`}>
                    {gifSrc ? (
                      <img
                        src={gifSrc}
                        alt={`${it.label} preview`}
                        loading="lazy"
                        className="gif-asset h-28 sm:h-32 md:h-40 lg:h-44 w-auto object-contain transition-transform duration-200"
                      />
                    ) : (
                      <div className="h-28 sm:h-32 md:h-40 lg:h-44 flex items-center justify-center text-white/60">
                        ({slug}.gif not found)
                      </div>
                    )}
                  </div>

                  {/* Text */}
                  <div className={`md:col-span-7 ${isEven ? "" : "md:order-1"}`}>
                    <h4 className="text-2xl md:text-3xl font-extrabold tracking-tight">
                      <span className="bg-gradient-to-r from-blue-300 via-white to-blue-300 bg-clip-text text-transparent">
                        {it.label}
                      </span>
                    </h4>
                    {it.desc && <p className="mt-2 text-white/75">{it.desc}</p>}
                    <div className="mt-4 inline-flex items-center gap-2 text-sm font-semibold underline underline-offset-4">
                      Explore →
                    </div>
                  </div>
                </div>
              </Link>
            );
          })}
        </div>

        {/* Company-Specific — logo-only, 4 on top / 2 centered below */}
        <div className="text-center mt-16 mb-8 md:mb-10">
          <h3 className="text-3xl md:text-5xl font-extrabold tracking-tight">
            <span className="bg-gradient-to-r from-green-300 via-white to-green-300 bg-clip-text text-transparent">
              Company-Specific Mock Interviews
            </span>
          </h3>
          <p className="mt-3 text-white/75 text-sm md:text-base">
            Drill real patterns from FAANG+ and top product companies
          </p>
          <div className="mx-auto mt-5 h-[2px] w-28 md:w-36 bg-gradient-to-r from-transparent via-green-400 to-transparent rounded-full" />
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-10 md:gap-12 place-items-center">
          {MI_COMPANIES.map((it, i) => {
            const lastTwoCentered =
              MI_COMPANIES.length === 6 && (i === 4 ? "lg:col-start-2" : i === 5 ? "lg:col-start-3" : "");
            return (
              <Link
                key={it.to}
                to={it.to}
                className={`group block w-full ${lastTwoCentered}`}
                aria-label={`Practice ${it.label} interview`}
                title={it.label}
              >
                <div className="h-12 sm:h-14 md:h-16 lg:h-20 flex items-center justify-center">
                  <img
                    src={it.logo}
                    alt={it.label}
                    loading="lazy"
                    className="company-logo max-h-full max-w-[180px] w-auto object-contain transition duration-200 opacity-80 group-hover:opacity-100 group-hover:scale-105"
                  />
                </div>
              </Link>
            );
          })}
        </div>
      </div>

      {/* Hovers */}
      <style>{`
        /* Soft glow on GIF itself */
        .gif-asset {
          filter: drop-shadow(0 0 0 rgba(74, 222, 128, 0));
        }
        .group\\/row:hover .gif-asset {
          filter: drop-shadow(0 0 16px rgba(74, 222, 128, 0.5));
          transform: scale(1.03);
        }
        /* Logo hover */
        .company-logo {
          filter: drop-shadow(0 0 0 rgba(74, 222, 128, 0));
        }
        .group:hover .company-logo {
          filter: drop-shadow(0 0 14px rgba(74, 222, 128, 0.55));
        }
      `}</style>
    </Section>
  );
}
