// src/components/Chatbot.jsx
import React, { useEffect, useRef, useState } from "react";

const Chatbot = ({ isOpen, toggleChatbot }) => {
  const [messages, setMessages] = useState([
    {
      sender: "bot",
      text:
        "Hi! I’m your AI assistant for TutorSimula. Ask me about the Mock Interview program, pricing, or anything else!",
    },
  ]);
  const [userInput, setUserInput] = useState("");
  const messagesEndRef = useRef(null);

  // Vite-only env (no process.env in browser)
  const API_BASE = import.meta?.env?.VITE_API_BASE || "";

  const handleSendMessage = async () => {
    if (!userInput.trim()) return;
    setMessages((prev) => [...prev, { sender: "user", text: userInput }]);

    try {
      const url = `${API_BASE}/api/chat`;
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: userInput }),
      });

      if (!res.ok) {
        console.error("Chat API error:", res.status, res.statusText, "URL:", url);
        throw new Error(`HTTP ${res.status}`);
      }

      const data = await res.json();
      const botResponse =
        data.fulfillmentText ||
        "Sorry, I didn’t understand that. Try asking about Mock Interview or pricing!";

      const richResponse = data.fulfillmentMessages?.find(
        (m) => m.message === "suggestion"
      );
      const suggestions = richResponse?.suggestions?.suggestions || [];

      setMessages((prev) => [
        ...prev,
        { sender: "bot", text: botResponse, suggestions },
      ]);
    } catch (err) {
      console.error("Chat API call failed:", err);
      setMessages((prev) => [
        ...prev,
        { sender: "bot", text: "Oops, something went wrong. Please try again later!" },
      ]);
    } finally {
      setUserInput("");
    }
  };

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  return (
    <div className="fixed top-1/2 right-4 transform -translate-y-1/2 z-[900] sm:bottom-4 sm:top-auto sm:transform-none">
      {!isOpen && (
        <div className="relative group">
          <button
            onClick={toggleChatbot}
            className="bg-green-600 text-white p-4 rounded-full shadow-lg hover:bg-green-700 transition-all duration-300 animate-blink"
            aria-label="Open TutorSimula AI Assistant"
          >
            💬
          </button>
          <span className="absolute right-full top-1/2 -translate-y-1/2 mr-2 bg-gray-800 text-white text-sm rounded p-2 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none">
            TutorSimula AI Assistant
          </span>
        </div>
      )}

      {isOpen && (
        <div className="bg-gray-900 w-80 h-96 rounded-lg shadow-2xl flex flex-col">
          <div className="bg-blue-900 text-white p-4 rounded-t-lg flex justify-between items-center">
            <span>TutorSimula AI Assistant</span>
            <button
              onClick={toggleChatbot}
              className="text-white text-lg hover:text-gray-300"
              aria-label="Close TutorSimula AI Assistant"
            >
              ✕
            </button>
          </div>

          <div className="flex-1 p-4 overflow-y-auto">
            {messages.map((msg, i) => (
              <div
                key={i}
                className={`mb-2 ${
                  msg.sender === "user" ? "text-right" : "text-left"
                }`}
              >
                <span
                  className={`inline-block p-2 rounded-lg ${
                    msg.sender === "user"
                      ? "bg-blue-600 text-white"
                      : "bg-gray-700 text-gray-200"
                  }`}
                >
                  {msg.text}
                </span>
                {msg.suggestions && (
                  <div className="mt-2 flex gap-2">
                    {msg.suggestions.map((s, idx) => (
                      <a
                        key={idx}
                        href={s.link || "#"}
                        className="bg-blue-500 text-white px-3 py-1 rounded hover:bg-blue-600"
                      >
                        {s.title}
                      </a>
                    ))}
                  </div>
                )}
              </div>
            ))}
            <div ref={messagesEndRef} />
          </div>

          <div className="p-4 border-t border-gray-600">
            <input
              type="text"
              value={userInput}
              onChange={(e) => setUserInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleSendMessage()}
              placeholder="Ask about Mock Interview..."
              className="w-full p-2 rounded bg-gray-700 text-white border border-gray-600 focus:outline-none"
            />
          </div>
        </div>
      )}

      <style>{`
        @keyframes blink { 0%{opacity:1} 50%{opacity:.5} 100%{opacity:1} }
        .animate-blink { animation: blink 1.5s ease-in-out infinite; }
        @media (prefers-reduced-motion: reduce) { .animate-blink { animation: none; } }
      `}</style>
    </div>
  );
};

export default Chatbot;
