// src/components/launch/sections/ProductsSection.jsx
import React from "react";
import { Link } from "react-router-dom";
import Section from "../Section.jsx";
import { PRODUCTS } from "../../../data/launchData.js"; // [{label, desc, to, icon?, badges?}]

function CTA({ to, label = "Try free" }) {
  return (
    <Link
      to={to}
      className="inline-flex items-center px-3 py-1.5 rounded-full
                 bg-gradient-to-r from-blue-400 via-blue-300 to-blue-400
                 hover:from-blue-300 hover:via-blue-400 hover:to-blue-500
                 text-black font-semibold text-sm transition
                 focus:outline-none focus:ring-2 focus:ring-blue-300/70
                 focus:ring-offset-2 focus:ring-offset-transparent"
      aria-label={label}
    >
      {label}
      <span className="ml-1">→</span>
    </Link>
  );
}

/** Unified, centered product card with gentle glow on hover */
function ProductCard({ item, className = "" }) {
  return (
    <div
      role="article"
      className={`product-card rounded-2xl bg-white/8 border border-white/10 px-6 py-6
                  transition min-h-[160px] flex flex-col items-center text-center
                  hover:bg-white/10 focus-within:bg-white/12 ${className}`}
    >
      <div className="text-2xl leading-none select-none opacity-90 mb-3">{item.icon ?? "✨"}</div>

      <h5 className="text-base md:text-lg font-semibold">{item.label}</h5>

      {item.desc && (
        <p className="text-white/75 mt-2 max-w-[40ch]">
          {item.desc}
        </p>
      )}

      {item.badges?.length ? (
        <div className="mt-2 flex flex-wrap gap-2 justify-center">
          {item.badges.map((b) => (
            <span key={b} className="text-xs bg-white/10 border border-white/10 px-2 py-0.5 rounded">
              {b}
            </span>
          ))}
        </div>
      ) : null}

      <div className="mt-4">
        <CTA to={item.to} />
      </div>
    </div>
  );
}

export default function ProductsSection() {
  // Top row: first three in order
  const topRow = PRODUCTS.slice(0, 3);

  // Bottom row: prefer QOTD + TOTD; else next two
  const remaining = PRODUCTS.slice(3);
  const preferredBottom = remaining.filter(
    (p) =>
      /question\s*of\s*the\s*day/i.test(p.label) ||
      /task\s*of\s*the\s*day/i.test(p.label)
  );
  const bottomRow = preferredBottom.length === 2 ? preferredBottom : remaining.slice(0, 2);

  return (
    <Section id="products">
      {/* Centered heading & subtitle with violet gradient */}
      <div className="text-center mb-8 md:mb-10">
        <h2 className="text-3xl md:text-5xl font-extrabold tracking-tight">
          <span className="bg-gradient-to-r from-blue-300 via-white to-blue-300 bg-clip-text text-transparent">
            Products
          </span>
        </h2>
        <p className="mt-2 text-white/75 text-sm md:text-base">
          Start with free tools that accelerate your prep.
        </p>
        <div className="mx-auto mt-5 h-[2px] w-28 md:w-36 bg-gradient-to-r from-transparent via-blue-300 to-transparent rounded-full" />
      </div>

      <div className="mx-auto max-w-6xl px-3 sm:px-4">
        {/* Row 1: exactly three tiles */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5 md:gap-6">
          {topRow.map((it) => (
            <ProductCard key={it.to} item={it} />
          ))}
        </div>

        {/* Row 2: two tiles centered */}
        <div className="mt-5 md:mt-6">
          <div className="flex flex-col sm:flex-row sm:justify-center gap-5 md:gap-6">
            {bottomRow.map((it) => (
              <div key={it.to} className="sm:w-[min(28rem,42vw)] lg:w-[28rem]">
                <ProductCard item={it} />
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Gentle violet glow + lift */}
      <style>{`
        .product-card {
          transform: translateY(0);
          box-shadow: 0 0 0 rgba(168, 85, 247, 0); /* violet-500 */
        }
        .product-card:hover,
        .product-card:focus-within {
          transform: translateY(-2px);
          box-shadow: 0 0 18px rgba(168, 85, 247, 0.25);
          border-color: rgba(168, 85, 247, 0.38);
        }
      `}</style>
    </Section>
  );
}
