// src/components/launch/sections/PricingSection.jsx
import React from "react";
import Section from "../Section.jsx";
import { Link } from "react-router-dom";

function Plan({ name, price, features }) {
  return (
    <div className="bg-white/10 border border-white/15 rounded-xl p-6">
      <div className="text-xl font-bold">{name}</div>
      <div className="mt-1 text-white/80">{price}</div>
      <ul className="mt-4 space-y-1 text-white/80 text-sm">
        {features.map((f) => <li key={f}>• {f}</li>)}
      </ul>
      <Link to="/pricing" className="inline-block mt-5 bg-green-400 hover:bg-green-300 text-gray-900 px-4 py-2 rounded-lg font-semibold">
        See pricing
      </Link>
    </div>
  );
}

export default function PricingSection() {
  return (
    <Section id="pricing" title="Pricing" subtitle="Simple plans for students and professionals.">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-6">
        <Plan name="Free" price="$0" features={["1 interview session", "Resume tools (basic)", "Question of the Day"]} />
        <Plan name="Pro" price="$9/mo" features={["Unlimited interviews", "Avatar mock & analytics", "Resume Analyzer (full)"]} />
        <Plan name="Teams" price="Custom" features={["Institutions & hiring teams", "Admin dashboard", "Priority support"]} />
      </div>
    </Section>
  );
}
